const EXCL = new Set(['pst','ps','cus','pt_old']);
const langList = $('Get Languages').first().json.languages;
const idToIso = {}; langList.forEach(l => idToIso[l.lang_id] = l.lang_iso);
const targets = langList.map(l => l.lang_iso).filter(i => i !== 'en' && !EXCL.has(i));
let all = [];
for (const it of $('Get Keys').all()) { if (!Array.isArray(it.json.keys)) throw new Error('keys missing: ' + JSON.stringify(it.json).slice(0,300)); all = all.concat(it.json.keys); }
const tr = (k, iso) => { const t = (k.translations||[]).find(x => x.language_iso === iso); if (!t) return ''; return typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); };
const isEmpty = (k, iso) => { const t = (k.translations||[]).find(x => x.language_iso === iso); if (!t) return true; const v = t.translation; if (typeof v === 'string') return v.trim() === ''; if (v && typeof v === 'object') return Object.values(v).every(s => !String(s||'').trim()); return true; };
const name = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
const active = all.filter(k => !k.is_archived);
const untrans = active.filter(k => targets.some(i => isEmpty(k, i)) || isEmpty(k,'en'));
const norm = s => String(s||'').toLowerCase().replace(/<[^>]+>/g,' ').replace(/[^\p{L}\p{N}\s-]/gu,' ').replace(/\s+/g,' ').trim();
const toks = s => new Set(norm(s).split(' ').filter(Boolean));
const dice = (a,b) => { if (!a.size||!b.size) return 0; let n=0; for (const x of a) if (b.has(x)) n++; return 2*n/(a.size+b.size); };
const lev = (a,b) => { if (a===b) return 1; const m=a.length,n=b.length; if(!m||!n) return 0; let p=Array(n+1).fill(0).map((_,j)=>j); for(let i=1;i<=m;i++){ const c=[i]; for(let j=1;j<=n;j++) c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1)); p=c;} return 1-p[n]/Math.max(m,n); };
const donors = active.filter(k => !untrans.includes(k) && tr(k,'en').trim());
const donorTok = donors.map(k => toks(tr(k,'en')));
let terms = []; for (const it of $('Get Glossary').all()) { const d = it.json.data || it.json.glossary_terms || []; terms = terms.concat(d); }
const out = untrans.map(k => {
  const en = tr(k,'en'); const et = toks(en); const en_n = norm(en);
  const cands = donors.map((d,i) => ({d, s: dice(et, donorTok[i])})).filter(x => x.s >= 0.4).sort((a,b)=>b.s-a.s).slice(0,25)
    .map(x => ({ d: x.d, s: lev(en_n, norm(tr(x.d,'en'))) })).filter(x => x.s >= 0.55).sort((a,b)=>b.s-a.s).slice(0,4);
  const missing = targets.filter(i => isEmpty(k,i));
  const g = terms.filter(t => { const tt = norm(t.term); return tt && new RegExp('(^|\\s)'+tt.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(\\s|$)').test(en_n); })
    .map(t => ({ term: t.term, desc: t.description, forbidden: t.forbidden, translatable: t.translatable, tr: Object.fromEntries((t.translations||[]).filter(x=>x.translation).map(x => [idToIso[x.langId] || x.langId, x.translation])) }));
  return {
    key_id: k.key_id, key: name(k), tags: k.tags, description: k.description, is_plural: k.is_plural, char_limit: k.char_limit,
    en, missing, existing: Object.fromEntries(targets.filter(i => !isEmpty(k,i)).map(i => [i, tr(k,i)])),
    fuzzy: cands.map(x => ({ key: name(x.d), score: +x.s.toFixed(2), en: tr(x.d,'en'), tr: Object.fromEntries(missing.map(i => [i, tr(x.d,i)])) })),
    glossary: g
  };
});
const ctxKeys = active.filter(k => /gender|non[- ]?binary|\bmale\b|\bfemale\b|\bman\b|\bwoman\b/i.test(tr(k,'en')) && !untrans.includes(k)).slice(0,40)
  .map(k => ({ key: name(k), en: tr(k,'en'), tr: Object.fromEntries(targets.map(i => [i, tr(k,i)])) }));
return [{ json: { total_keys: all.length, active: active.length, targets, untranslated_count: out.length, glossary_terms: terms.length, untranslated: out, gender_context: ctxKeys } }];
